function total(a){return a.reduce(function(s,x){return s+(Number(x.amount)||0);},0);}
function auditSnapshot(x){var keys=['name','type','machineId','date','amount','quantity','rate','basis','material','customerId','customerName','status','serviceType','meterType','meterReading','supplier','method','reference','allocations','driverId','plate','make','capacity','ownership','rateMode','destination','origin','ticket','description','nextServiceDate','nextServiceMeter','driverName','licenceExpiry','period','daysWorked','baseSalary','dailyIncentive','incentiveAmount','advance','deductions','netAmount','component'];var o={};keys.forEach(function(k){if(x&&x[k]!==undefined)o[k]=x[k];});return o;}
