function driver(id){return state.drivers.find(function(x){return x.id===id;});}function licenceStatus(d){if(!d||!d.licenceExpiry)return 'Expiry date not recorded';var days=Math.ceil((Date.parse(d.licenceExpiry+'T00:00:00Z')-Date.parse(today()+'T00:00:00Z'))/86400000);return days<0?'EXPIRED':days<=30?'Expires in '+days+' days':'Valid until '+d.licenceExpiry;}
