function paymentAllocations(ids,amount,cId,mId,excludePaymentId){var unique=Array.from(new Set((ids||[]).filter(Boolean))),rows=[];for(var i=0;i<unique.length;i++){var t=byKind('trip',unique[i]);if(!t||t.customerId!==cId||t.machineId!==mId)return null;var paid=state.payments.reduce(function(sum,p){if(p.id===excludePaymentId)return sum;return sum+(p.allocations||[]).reduce(function(n,a){return n+(a.tripId===t.id?(Number(a.amount)||0):0);},0);},0),due=Math.max(0,(Number(t.amount)||0)-paid);if(due>0.005)rows.push({trip:t,due:due});}rows.sort(function(a,b){return String(a.trip.date||'').localeCompare(String(b.trip.date||''))||String(a.trip.id).localeCompare(String(b.trip.id));});var totalDue=rows.reduce(function(n,r){return n+r.due;},0);if(amount>totalDue+0.005)return null;var left=amount,out=[];rows.forEach(function(r){if(left>0.005){var part=Math.min(left,r.due);out.push({tripId:r.trip.id,amount:Math.round(part*100)/100});left-=part;}});return left>0.005?null:out;}
