var ts=state.trips.filter(function(t){return t.date>=rf&&t.date<=rt&&(rm==='all'||t.machineId===rm);}),es=state.expenses.filter(function(x){return x.date>=rf&&x.date<=rt&&(rm==='all'||x.machineId===rm);}),ps=state.payments.filter(function(p){return p.date>=rf&&p.date<=rt&&(rm==='all'||p.machineId===rm);});
var inc=total(ts),cost=total(es),cash=total(ps),fuel=es.filter(function(x){return x.type==='Fuel';}),litres=fuel.reduce(function(n,x){return n+(Number(x.quantity)||0);},0);
